import binascii

admin_hex = '0c76c163b50e679f2cbec8ee11e47801cecc649363d2168892'
length = len(admin_hex)

substr_min = 32
substr_max = 48
found_candidates = []

for sublen in range(substr_min, substr_max+1, 2):
    for start in range(0, length - sublen + 1, 2):
        substr = admin_hex[start:start+sublen]
        try:
            bytes_out = binascii.unhexlify(substr)
            try:
                dec = bytes_out.decode('ascii')
            except UnicodeDecodeError:
                continue
            info = {'substr': substr, 'decoded': dec, 'candidate_flag': None}
            if 'flag' in dec or dec.startswith('flag'):
                candidate = f'flag{{{dec}}}' if not dec.startswith('flag{') else dec
                info['candidate_flag'] = candidate
                found_candidates.append(info)
            else:
                found_candidates.append(info)
        except Exception:
            continue

for i in found_candidates:
    print("Substring:", i['substr'])
    print("Decoded Output:", i['decoded'])
    print("Flag-like?", 'flag' in i['decoded'] or i['decoded'].startswith('flag'))
    if i['candidate_flag']:
        print('CANDIDATE FLAG:', i['candidate_flag'])
    print('-'*50)

