import string

hex_str = '0c76c163b50e679f2cbec8ee11e47801cecc649363d2168892'
min_len = 32
max_len = 48

valid_flags = []
output = []

for strlen in range(min_len, max_len + 1, 2):
    for i in range(0, len(hex_str) - strlen + 1):
        sub = hex_str[i:i+strlen]
        try:
            b = binascii.unhexlify(sub)
            txt = b.decode('ascii')
            printable_ratio = sum(c in string.printable for c in txt)/len(txt)
            looks_flag = 'flag{' in txt or txt.startswith('flag') or txt.startswith('{flag')
            valid = printable_ratio > 0.8 and ('flag{' in txt or '}' in txt)
            entry = {
                'substring': sub,
                'decoded': txt,
                'flag_like': looks_flag or valid
            }
            if valid:
                valid_flags.append(txt)
            output.append(entry)
        except Exception:
            continue
with open('/home/ctfplayer/ctf_files/polly_extract_substrings.out', 'w') as f:
    for entry in output:
        flag_note = ' [CANDIDATE FLAG!]' if entry['flag_like'] else ''
        f.write(f"Sub: {entry['substring']} => Decoded: {entry['decoded']}{flag_note}\n")
    if valid_flags:
        for cand in valid_flags:
            f.write(f"Possible flag: flag{{{cand}}}\n")

